def is_prime(n):
    """Check if a number n is prime."""
    if n <= 1: 
        return False

    for i in range(2, int(n**0.5) + 1): 
        if n % i == 0: 
            return False
    return True

def primes_up_to(limit):
    """
    Return a list of prime numbers less than or equal to limit.

    >>> primes_up_to(10)
    [2, 3, 5, 7]
    >>> primes_up_to(20)
    [2, 3, 5, 7, 11, 13, 17, 19]
    """
    result = []
    for num in range(2, limit + 1):
        if is_prime(num):
            result.append(num)
    return result
```

